
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wb97x_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wb97x_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.343522182858426e+00, -3.278571731824235e+00, -3.187627393087840e+00, -3.061808690840139e+00, -2.890757517833669e+00, -2.664032749682956e+00, -2.374252147337746e+00, -2.022067417835628e+00, -1.620140237728741e+00, -1.193186075208182e+00, -7.967541807053928e-01, -5.062357864732914e-01, -4.301064748347928e-01, -3.366621655945872e-01, -2.208157541014512e-01, -1.095136830970951e-01, -4.603630352502672e-02, -6.887993026187982e-03, -1.240379077695949e-03, -2.481498912210147e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


